mapper.select:
select t1.id, t1.version, t1.description, t1.version_status, t1.status as status_int_value from bp_code_rule_version t1 where t1.is_deleted = 0
and t1.rule_code = #{code}
order by t1.create_time desc

mapper.delete:
update bp_code_rule_version
set del_version_flag = id,
    is_deleted      = 1,
    update_time   = now(),
    update_by     = #{userId}
where id = #{id}
